import{_ as t,o as a,c,a2 as o}from"./chunks/framework.DXa1R37q.js";const f=JSON.parse('{"title":"Fetch and extraction","description":"","frontmatter":{},"headers":[],"relativePath":"searchable/fetching.md","filePath":"searchable/fetching.md","lastUpdated":1792947882000}'),r={name:"searchable/fetching.md"};function d(n,e,i,s,h,l){return a(),c("div",null,[...e[0]||(e[0]=[o('<h1 id="fetch-and-extraction" tabindex="-1">Fetch and extraction <a class="header-anchor" href="#fetch-and-extraction" aria-label="Permalink to &quot;Fetch and extraction&quot;">​</a></h1><p><code>web_fetch</code> tries <code>fetch.strategies</code> in order. The default order is <code>direct</code>, <code>jina</code>, then <code>wayback</code>.</p><p>Direct fetch accepts HTML and XHTML. Mozilla Readability extracts the article, and Turndown converts it to Markdown with ATX headings and fenced code blocks. Empty extraction, unsupported content types, oversized decoded bodies, and oversized Markdown fail.</p><p>Jina Reader returns Markdown from its fixed HTTPS origin. Wayback first checks the fixed availability API, then accepts only an HTTPS snapshot URL on <code>web.archive.org</code>. Searchable does not disclose target URLs containing credentials or query strings to either third party. In that case it skips remote fallback and reports a bounded strategy code.</p><p><code>fetch.timeout_ms</code> limits each attempt. <code>fetch.overall_timeout_ms</code> limits the complete strategy sequence. The returned <code>source</code> is <code>direct</code>, <code>jina</code>, or <code>wayback</code>, while <code>url</code> remains the original target. Cancellation stops the current request and prevents the next strategy.</p>',5)])])}const _=t(r,[["render",d]]);export{f as __pageData,_ as default};
